const mapState={showAll:false,zoom:1,center:[-71.112,42.378],selected:'ALBANY ST & MASSACHUSETTS AVE',rows:[]};
function renderMap(rows){mapState.rows=rows;const compact=window.innerWidth<600,W=800,H=480,scale=7600*mapState.zoom,project=c=>[W/2+(c[0]-mapState.center[0])*.74*scale,H/2-(c[1]-mapState.center[1])*scale];
 const matched=D.locations.filter(l=>l.coord).map(l=>({...l,rs:rows.filter(r=>r[0]===l.name)})).filter(l=>sum(l.rs)>0),shown=matched.filter(l=>mapState.showAll||names.has(l.name)||$('location').value===l.name);
 if($('location').value!=='all')mapState.selected=$('location').value;const choice=matched.find(l=>l.name===mapState.selected),covered=matched.reduce((s,l)=>s+sum(l.rs),0),unresolved=sum(rows.filter(r=>r[0]==='Unresolved location'));
 $('map-shortlist').setAttribute('aria-pressed',String(!mapState.showAll));$('map-all').setAttribute('aria-pressed',String(mapState.showAll));
 $('map-scope').textContent=`Showing ${shown.length} ${$('location').value!=='all'?'selected verified intersections':mapState.showAll?'verified intersections':'mapped shortlist candidates'} and ${shown.reduce((s,l)=>s+sum(l.rs),0)} crashes under the current year, involvement and intersection filters. Display choice does not change the study shortlist.`;
 let roads=(D.roadFeatures||[]).map(f=>`<path d="${f.points.map((c,i)=>{const p=project(c);return (i?'L':'M')+p[0].toFixed(1)+','+p[1].toFixed(1)}).join('')}" stroke="${f.major>=2?'#becdca':'#d9e3e0'}" stroke-width="${f.major>=2?1.8:1}"/>`).join('');
 const roadNames=['Massachusetts Ave','Cambridge St','Broadway','Hampshire St','Concord Ave','Brattle St','Memorial Dr'];let roadLabels=[];
 for(const name of roadNames){const candidates=(D.roadFeatures||[]).filter(f=>f.name===name).map(f=>{const p=project(f.points[Math.floor(f.points.length/2)]);return {p,f}}).filter(o=>o.p[0]>75&&o.p[0]<W-100&&o.p[1]>40&&o.p[1]<H-40);const c=candidates[Math.floor(candidates.length/2)];if(c&&!roadLabels.some(l=>Math.hypot(l.p[0]-c.p[0],l.p[1]-c.p[1])<80))roadLabels.push({name,p:c.p})}
 const visible=shown.map(l=>({...l,p:project(l.coord)})).filter(l=>l.p[0]>-20&&l.p[0]<W+20&&l.p[1]>-20&&l.p[1]<H+20);
 const circles=visible.sort((a,b)=>Number(names.has(a.name))-Number(names.has(b.name))||sum(b.rs)-sum(a.rs)).map(l=>{const chosen=l.name===mapState.selected,letter=names.has(l.name)?'ABCDEF'[shortlist.findIndex(q=>q.name===l.name)]:'';return `<g role="button" tabindex="0" data-location="${esc(l.name)}" aria-label="${esc(nice(l.name))}: ${sum(l.rs)} crashes. Inspect location.">${chosen?`<circle cx="${l.p[0]}" cy="${l.p[1]}" r="${Math.sqrt(sum(l.rs))*4+5}" fill="none" stroke="#b78445" stroke-width="2"/>`:''}<circle cx="${l.p[0]}" cy="${l.p[1]}" r="${Math.sqrt(sum(l.rs))*4}" fill="${letter?'#177d79':'#7192a7'}" fill-opacity="${letter?.9:.48}" stroke="${letter?'#172f46':'white'}" stroke-width="${letter?1.8:1}"/><title>${esc(nice(l.name))}: ${sum(l.rs)} eligible crashes; cyclist ${stats(l.rs)[1]}; pedestrian ${stats(l.rs)[2]}. Public intersection location.</title></g>`}).join('');
 const labels=visible.filter(l=>names.has(l.name)).sort((a,b)=>a.p[1]-b.p[1]);let lastY=-100;const labelSvg=labels.map((l,i)=>{const letter='ABCDEF'[shortlist.findIndex(q=>q.name===l.name)],text=compact?letter:letter+' · '+nice(l.name),lx=l.p[0]<400?Math.max(12,l.p[0]-240):Math.min(535,l.p[0]+28),ly=Math.max(28,Math.min(H-16-(labels.length-1-i)*30,Math.max(l.p[1]-15,lastY+30)));lastY=ly;return `<g role="button" tabindex="0" data-location="${esc(l.name)}" aria-label="${esc(nice(l.name))}: ${sum(l.rs)} crashes. Inspect label."><path d="M${l.p[0]},${l.p[1]} L${lx+12},${ly}" stroke="#4b7974" fill="none"/><rect x="${lx-5}" y="${ly-16}" width="${compact?45:253}" height="${compact?38:23}" rx="4" fill="white" fill-opacity=".96" stroke="#c4d5d0"/><text x="${lx+2}" y="${ly}" fill="#172f46" font-size="${compact?28:11.5}" font-weight="600">${esc(text)}</text></g>`}).join('');
 $('map').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="group" tabindex="0" aria-label="Cambridge intersection map. Arrow keys pan, plus and minus zoom."><defs><clipPath id="mapclip"><rect width="800" height="480"/></clipPath></defs><g clip-path="url(#mapclip)"><g fill="none">${roads}</g>${roadLabels.map(l=>`<text x="${l.p[0]}" y="${l.p[1]}" text-anchor="middle" font-size="10" fill="#62756e" stroke="#f0f5f3" stroke-width="4" paint-order="stroke">${esc(l.name)}</text>`).join('')}${circles}${labelSvg}</g><text x="747" y="28" fill="#172f46" font-size="13">N ↑</text><path d="M25 446v6h${.00599*.74*scale}v-6" stroke="#536573" fill="none"/><text x="25" y="438" font-size="10" fill="#536573">500 m approx.</text></svg>${compact?`<div class="mobile-map-choices">${shown.filter(l=>names.has(l.name)).map(l=>`<button data-location="${esc(l.name)}">${'ABCDEF'[shortlist.findIndex(q=>q.name===l.name)]} · ${esc(nice(l.name))}</button>`).join('')}</div>`:''}`;
 const svg=$('map').querySelector('svg');let drag=null;
 svg.onpointerdown=e=>{if(e.target.closest('[data-location]'))return;drag={x:e.clientX,y:e.clientY,center:[...mapState.center]};svg.setPointerCapture(e.pointerId)};
 svg.onpointerup=e=>{if(!drag)return;const ratio=W/svg.getBoundingClientRect().width;mapState.center=[drag.center[0]-(e.clientX-drag.x)*ratio/(.74*scale),drag.center[1]+(e.clientY-drag.y)*ratio/scale];drag=null;renderMap(mapState.rows)};
 svg.onkeydown=e=>{if(e.target!==svg)return;const pan=65/scale;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')mapState.center[0]-=pan/.74;if(e.key==='ArrowRight')mapState.center[0]+=pan/.74;if(e.key==='ArrowUp')mapState.center[1]+=pan;if(e.key==='ArrowDown')mapState.center[1]-=pan;if(e.key==='+'||e.key==='=')mapState.zoom=Math.min(8,mapState.zoom*1.5);if(e.key==='-')mapState.zoom=Math.max(1,mapState.zoom/1.5);renderMap(mapState.rows);$('map').querySelector('svg').focus()}};
 $('map').querySelectorAll('[data-location]').forEach(g=>{const select=()=>{mapState.selected=g.dataset.location;renderMap(mapState.rows)};g.onclick=select;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();select();$('map-detail').focus()}}});
 $('map-detail').setAttribute('tabindex','-1');
 if(choice){const ss=stats(choice.rs);$('map-detail').innerHTML=`<div class="eyebrow">${names.has(choice.name)?'STUDY CANDIDATE '+('ABCDEF'[shortlist.findIndex(l=>l.name===choice.name)]):'VERIFIED INTERSECTION'}</div><h3>${esc(nice(choice.name))}</h3><strong class="map-count">${ss[0]} <small>reported crashes</small></strong><p class="note">Current filter selection. Counts are not exposure-adjusted.</p><dl><div><dt>Cyclist-involved</dt><dd>${ss[1]}</dd></div><div><dt>Pedestrian-involved</dt><dd>${ss[2]}</dd></div><div><dt>2023 / 2024 / 2025</dt><dd>${[2023,2024,2025].map(yr=>sum(choice.rs.filter(r=>r[1]===yr))).join(' / ')}</dd></div></dl><button id="map-focus">Zoom to this intersection</button>${names.has(choice.name)?'<button id="map-audit">Read the intersection review →</button>':''}<p class="note">Verified unique street-pair match. Injury information is available only in fixed, broad shortlist summaries.</p>`;$('map-focus').onclick=()=>{mapState.center=[...choice.coord];mapState.zoom=4;renderMap(mapState.rows)};if($('map-audit'))$('map-audit').onclick=()=>{window.selectAudit(choice.name);$('audit-workspace').scrollIntoView({behavior:'smooth'})}}
 else $('map-detail').innerHTML='<div class="eyebrow">INSPECT A LOCATION</div><h3>Select a named circle</h3><p>Read its aggregate counts and open its intersection review. Some study candidates may be outside the current filters or lack a verified map match.</p>';
 $('map-unresolved').innerHTML='<strong>D · Brattle St & Craigie St is not plotted.</strong> Its official GIS match is unresolved or ambiguous. It remains on the six-location shortlist; confirm the precise intersection during preparation.';
 $('coverage').textContent=`Mapping coverage under current filters: ${covered} of ${sum(rows)} crashes at ${matched.length} verified intersections. Unresolved: ${unresolved} with no publishable public pair; ${sum(rows)-covered-unresolved} at unmatched or ambiguous public pairs. Full study: 322 / 696 crashes (46.3%) mapped, at 200 nodes. Of 290 source intersection pairs, 90 lack a unique match. Six address-like or non-public labels are withheld and grouped with 266 no-pair records in the 272-record public unresolved summary.`;
}
function initializeMap(){ $('map-shortlist').onclick=()=>{mapState.showAll=false;renderMap(mapState.rows)};$('map-all').onclick=()=>{mapState.showAll=true;renderMap(mapState.rows)};$('map-zoom-in').onclick=()=>{mapState.zoom=Math.min(8,mapState.zoom*1.5);renderMap(mapState.rows)};$('map-zoom-out').onclick=()=>{mapState.zoom=Math.max(1,mapState.zoom/1.5);renderMap(mapState.rows)};$('map-fit').onclick=()=>{mapState.zoom=1;mapState.center=[-71.112,42.378];renderMap(mapState.rows)}}
window.addEventListener('DOMContentLoaded',initializeMap);

window.addEventListener('resize',()=>renderMap(mapState.rows));
